{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Tetrabenazine, a close structural analogue sharing the benzoquinolizine core and ketone, had very low oral systemic availability in patients (mean 0.049 ± 0.032), directly supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Meptazinol, a basic tertiary amine with phenolic/aromatic features, showed absolute oral bioavailability of 4.5–8.7% in humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Pentazocine, a related analgesic with a phenolic group and N-methyl, had mean oral bioavailability of 18% in healthy subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "2-Methoxyestradiol, a phenolic methoxy steroid, had oral bioavailability of only 1–2% in patients, supporting low F for methoxy-phenol-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Estradiol, a phenolic steroid, had absolute oral bioavailability of about 5% (range 1–12%) in humans, supporting low F for phenolic compounds subject to first-pass conjugation.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close analogue of tetrabenazine, which has very low oral bioavailability (~5%) in humans; multiple structurally related phenolic/methoxy basic drugs also show F <20%. Therefore predict low.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for the exact query molecule.",
    "The phenolic OH may alter absorption and first-pass metabolism relative to tetrabenazine.",
    "Formulation and dose effects on bioavailability are unknown for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

